(* [comment removed for export] *)
(* [comment removed for export] *)
Definition pop_ms (total mu : Z) : Z := round_up (total - mu) kUserMapSize.

Definition pop_map_seg1_post (ra sp gp tp t0 t1 t2 s0 s1 a6 s5v s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (s2 s3 s4 s5 s6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo R stat rbeg mu total : Z) : machine_state -> Prop :=
  fun ms' => exists m' (j44 : list byte),
    let beg := rbeg + mu in let ms := pop_ms total mu in
    ms' = MS (mkR (wz 0x088a18) (Z_to_bv 64 (bv_unsigned sp + -192)) gp tp t0 t1 t2 (wz ms) (wz 1) (wz beg) (wz ms) (wz 3) (wz 50) (Z_to_bv 64 (-1)) (wz 0) a6 (wz 222)
                  (wz beg) (wz 0x18564) (wz APAGESZ) s5v (wz AINST) s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x086c58) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 464, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -192)
    /\ rw_cells bsegs m' (bv_unsigned sp + -192) [C4 (wz 50); CB 44 j44; C8 (wz beg); C8 (wz ms); C8 (wz rbeg); C8 (wz beg); C8 (wz ms); C8 (wz 0x092084)]   (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -96) [C8 (wz rbeg); C8 (wz stat); C8 (wz R); C8 (wz 0x5548c)]                                               (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Section MapSeg1.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a2 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo c R stat sb k nf mfa au mu : Z) (j64 : list byte).
  Let csz := class_size c. Let total := au + csz * k. Let rbeg := sb + c * 2^32.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -64).
