(* [comment removed for export] *)
(* [comment removed for export] *)
Definition pop_mid_map_post (sp gp tp t0 t1 t2 a6 x6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (fs : list cell) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo R rbeg csz au mu n nf mfa : Z) : machine_state -> Prop :=
  fun ms' => exists m' (j8 j44 : list byte),
    let cur := rbeg + kFreeArrayOffset + mfa in let sz := efs_new (nf + n) - mfa in
    ms' = MS (mkR (wz 0x088a18) (Z_to_bv 64 (bv_unsigned sp + -240)) gp tp t0 t1 t2 (wz sz) (wz 1) (wz cur) (wz sz) (wz 3) (wz 50) (Z_to_bv 64 (-1)) (wz 0) a6 (wz 222)
                  (wz cur) (wz 0x1a751) (wz APAGESZ) (wz csz) x6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x086c58) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 512, bv_unsigned sp + -64)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -240)
    /\ rw_cells bsegs m' (bv_unsigned sp + -240) [C4 (wz 50); CB 44 j44; C8 (wz (mu - au)); C8 (wz R); C8 (wz sz); C8 (wz cur); C8 (wz sz); C8 (wz 0x092084)]   (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -144) [C8 (wz sz); C8 (wz cur); C8 (wz (efs_new (nf + n))); C8 (wz 0x530d0)]                                 (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -112) [CB 8 j8; C8 (wz n); C8 (wz rbeg); C8 (wz (nf + n)); C8 (wz R); C8 (wz 0x55500)]
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) fs.

Section MidMap.
  Variables (rax sp gp tp t0 t1 t2 x1 a1 a2 a4 a5 a6 a7 x3 x6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo R rbeg csz au mu nf mfa : Z) (fs : list cell).
  Let n := (mu - au) / csz.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -64).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 512 <= bv_unsigned sp.   (* [comment removed for export] *)
  Hypothesis F64 : rw_cells bsegs m (bv_unsigned sp + -64) fs. Hypothesis FSL : cells_size fs = 64%nat.
  Hypothesis RR : AHI_LO <= R /\ R + 128 <= aceil.
  Hypothesis RB : AHI_LO <= rbeg /\ rbeg + 2^32 <= aceil /\ rbeg mod 65536 = 0.
  Hypothesis CSZ : 32 <= csz <= 65536.
  Hypothesis AUR : 0 <= au <= mu /\ mu <= kFreeArrayOffset /\ 0 <= nf /\ mfa < 4 * (nf + n) /\ 4 * (nf + n) <= kFreeArraySize /\ 0 <= mfa /\ mfa mod kFreeArrayMapSize = 0.
  Hypothesis RI : rw_cells bsegs m R (rinfo_cells nf mfa au mu).
  Hypothesis PMH : rw_cells bsegs m (AINST + 56) [C8 (wz 0)].
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis PSC : rw_cells bsegs m APAGESZ [C8 (wz 4096)].
  Hypothesis DPM : rw_cells bsegs m (ACFLAGS + 260) [C1 (b8 0)].

  Theorem pop_mid_map :
    evt bsegs (pop_mid_map_post sp gp tp t0 t1 t2 a6 x6 s7 s8 s9 s10 s11 t3 t4 t5 t6 fs F fc m lo R rbeg csz au mu n nf mfa)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz R) x1 (wz AINST) a1 a2 (wz au) a4 a5 a6 a7
               (wz rbeg) x3 (wz mu) (wz csz) x6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
